mapper.select:
SELECT id, command_id, idempotency_key, request_hash, auction_window_id, campaign_id, bidder_user_id,
       post_id, resource_type, bid_amount, reserve_price, window_status, status, created_at, updated_at
FROM promotion_auction_command
WHERE auction_window_id = #{auctionWindowId}
  AND bidder_user_id = #{bidderUserId}
  AND idempotency_key = #{idempotencyKey}
LIMIT 1

